<template>
  <figure ref="figure" class="view-journey-demo index-ignore" :class="{'has-hover-zoom':hoverZoom}">
    <div class="view-journey-lead"><slot name="lead"></slot></div>
    <div ref="stage" class="view-journey-stage" :class="focus ? `is-focusing-${focus}` : ''">
      <section :class="{ 'is-receding': focus === 'exhibition' }">
        <header><span>Article</span><button v-if="!hoverZoom" type="button" :aria-label="focus === 'article' ? 'Show both presentations' : 'Enlarge the article'" :aria-pressed="focus === 'article'" @click.stop="toggleFocus('article')"><i aria-hidden="true"></i></button></header>
        <ExpandableProjectMedia title="Article demonstration" :aspect-ratio="8/5" pointer-preview @change="onEnlarged('article',$event)">
        <div ref="articleStage" class="view-journey-frame demo-open-surface">
          <div class="view-journey-content">
          <iframe inert v-if="mountedFrames" ref="articleFrame" :src="articleUrl" title="A View moving through its article presentation" :style="articleFrameStyle" tabindex="-1" @load="sendPlaybackState"></iframe>
          <img v-else-if="constrainedDevice" class="view-journey-poster" src="/assets/img/view-gallery/article-journey.webp?v=20260927-3" alt="The opening of The Places That Shaped Henry as an article">
          <div v-else class="view-journey-placeholder" aria-hidden="true"><i></i><i></i><i></i></div>
          </div>
          <DemoOpenLink v-if="expanded!=='article'" :href="articleOpenUrl" label="Open article" />
        </div>
        <template #caption><div v-if="expanded==='article'" class="view-journey-expanded-controls"><DemoOpenLink inline :href="articleOpenUrl" label="Open article" /><button v-if="mountedFrames" class="view-journey-transport" type="button" :aria-label="paused?'Continue demonstration':'Pause demonstration'" @click="paused=!paused"><svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="paused" d="m7 4 8 6-8 6Z"/><path v-else d="M7 4v12M13 4v12"/></svg></button></div></template>
        </ExpandableProjectMedia>
      </section>
      <div class="view-journey-link" aria-hidden="true"><i></i><span>Same place</span><i></i></div>
      <section :class="{ 'is-receding': focus === 'article' }">
        <header><span>Exhibition</span><button v-if="!hoverZoom" type="button" :aria-label="focus === 'exhibition' ? 'Show both presentations' : 'Enlarge the exhibition'" :aria-pressed="focus === 'exhibition'" @click.stop="toggleFocus('exhibition')"><i aria-hidden="true"></i></button></header>
        <ExpandableProjectMedia title="Exhibition demonstration" :aspect-ratio="8/5" pointer-preview @change="onEnlarged('exhibition',$event)">
        <div ref="exhibitionStage" class="view-journey-frame demo-open-surface">
          <div class="view-journey-content">
          <iframe inert v-if="mountedFrames" ref="exhibitionFrame" :src="exhibitionUrl" title="The same View moving through its exhibition presentation" :style="exhibitionFrameStyle" tabindex="-1" allow="autoplay 'none'; fullscreen" @load="sendPlaybackState"></iframe>
          <img v-else-if="constrainedDevice" class="view-journey-poster" src="/assets/img/view-gallery/exhibition-journey.webp?v=20260927-3" alt="The entrance to The Places That Shaped Henry as an exhibition">
          <div v-else class="view-journey-placeholder" aria-hidden="true"><i></i><i></i><i></i></div>
          </div>
          <DemoOpenLink v-if="expanded!=='exhibition'" :href="exhibitionOpenUrl" label="Open exhibition" />
        </div>
        <template #caption><div v-if="expanded==='exhibition'" class="view-journey-expanded-controls"><DemoOpenLink inline :href="exhibitionOpenUrl" label="Open exhibition" /><button v-if="mountedFrames" class="view-journey-transport" type="button" :aria-label="paused?'Continue demonstration':'Pause demonstration'" @click="paused=!paused"><svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="paused" d="m7 4 8 6-8 6Z"/><path v-else d="M7 4v12M13 4v12"/></svg></button></div></template>
        </ExpandableProjectMedia>
      </section>
    </div>
    <figcaption>
      <p>Each article section becomes a room that displays its original works as exhibits.</p>
      <button v-if="mountedFrames" class="view-journey-transport" type="button" :aria-label="paused ? 'Continue demonstration' : 'Pause demonstration'" @click="paused = !paused"><svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="paused" d="m7 4 8 6-8 6Z"/><path v-else d="M7 4v12M13 4v12"/></svg></button>
    </figcaption>
  </figure>
</template>

<script>
import { demoPreloadMargin, DEMO_RETAIN_MS } from '../../utils/demoPreload';
import DemoOpenLink from './DemoOpenLink.vue';
import ExpandableProjectMedia from './ExpandableProjectMedia.vue';
const BASE = { width: 1440, height: 900 };
export default {
  name: 'ViewPresentationJourneyDemo',
  components: { DemoOpenLink, ExpandableProjectMedia },
  props: { shareId: { type: String, default: 'PNZPdB__yBeyYjkF' }, enabled: { type: Boolean, default: true }, hoverZoom: Boolean },
  data: () => ({ visible: false, playbackVisible: false, pageVisible: true, frameKey: 0, articleScale: 1, exhibitionScale: 1, focus: '', expanded:'', paused: false, constrainedDevice: false }),
  computed: {
    mountedFrames() { return (this.visible||this.expanded) && !this.constrainedDevice; },
    channel() { return `view-journey-${this.frameKey}`; },
    routeBase() { return `${window.location.pathname}#/view/${this.shareId}`; },
    articleUrl() { return `${this.routeBase}?presentation=article&embedded=1&preview=1&galleryFrame=1&showcase=articleJourney&showcaseChannel=${this.channel}`; },
    exhibitionUrl() { return `${this.routeBase}?presentation=museum&galleryFrame=1&showcase=linkedJourney&showcaseChannel=${this.channel}`; },
    articleOpenUrl() { return `${this.routeBase}?presentation=article&temporaryPresentation=1`; },
    exhibitionOpenUrl() { return `${this.routeBase}?presentation=museum&temporaryPresentation=1`; },
    articleFrameStyle() { return this.frameStyle(this.articleScale); },
    exhibitionFrameStyle() { return this.frameStyle(this.exhibitionScale); },
    effectivePaused() { return this.paused || (!this.playbackVisible&&!this.expanded) || !this.pageVisible; },
  },
  mounted() {
    this.constrainedDevice = window.matchMedia('(max-width: 760px)').matches || (Number(navigator.deviceMemory || 0) > 0 && Number(navigator.deviceMemory) <= 4) || (Number(navigator.hardwareConcurrency || 0) > 0 && Number(navigator.hardwareConcurrency) <= 4);
    this._resize = new ResizeObserver(this.measure);
    this._resize.observe(this.$refs.articleStage);
    this._resize.observe(this.$refs.exhibitionStage);
    this._observer = new IntersectionObserver(entries => {
      if (entries.some(entry => entry.isIntersecting)) {
        clearTimeout(this._unmountTimer);
        this.visible = true;
        this.$nextTick(this.measure);
        return;
      }
      clearTimeout(this._unmountTimer);
      this._unmountTimer = setTimeout(() => { this.visible = false; }, DEMO_RETAIN_MS);
    }, { rootMargin: demoPreloadMargin() });
    this._observer.observe(this.$refs.stage);
    this._playbackObserver = new IntersectionObserver(entries => { this.playbackVisible = Boolean(entries[0]?.isIntersecting && entries[0].intersectionRatio >= .25); }, { threshold: [0, .25] });
    this._playbackObserver.observe(this.$refs.stage);
    this._visibility = () => { this.pageVisible = !document.hidden; };
    this._visibility(); document.addEventListener('visibilitychange', this._visibility);
    window.addEventListener('message', this.forwardPosition);
  },
  beforeUnmount() {
    clearTimeout(this._unmountTimer);
    this._observer?.disconnect(); this._playbackObserver?.disconnect(); this._resize?.disconnect();
    document.removeEventListener('visibilitychange', this._visibility);
    window.removeEventListener('message', this.forwardPosition);
  },
  watch: {
    effectivePaused() { this.sendPlaybackState(); },
  },
  methods: {
    onEnlarged(kind,value){this.expanded=value?kind:'';this.$nextTick(()=>{this.measure();this.sendPlaybackState();});},
    frameStyle(scale) { return { width: `${BASE.width}px`, height: `${BASE.height}px`, transform: `scale(${scale})` }; },
    measure() { this.articleScale = (this.$refs.articleStage?.clientWidth || BASE.width) / BASE.width; this.exhibitionScale = (this.$refs.exhibitionStage?.clientWidth || BASE.width) / BASE.width; },
    forwardPosition(event) {
      if (event.origin !== window.location.origin || ![this.$refs.articleFrame?.contentWindow, this.$refs.exhibitionFrame?.contentWindow].includes(event.source)) return;
      if(event.data?.type === 'view-gallery-showcase-ready' && event.data.channel === this.channel) { this.sendPlaybackState(); return; }
      if(event.source !== this.$refs.articleFrame?.contentWindow) return;
      const message = event.data; if (message?.type !== 'view-article-showcase-position' || message.channel !== this.channel) return;
      this.$refs.exhibitionFrame?.contentWindow?.postMessage({ type: 'view-exhibition-showcase-position', channel: this.channel, position: message.position }, window.location.origin);
    },
    sendPlaybackState() {
      const message = { type: 'view-gallery-showcase-playback', channel: this.channel, paused: this.effectivePaused };
      this.$refs.articleFrame?.contentWindow?.postMessage(message, window.location.origin);
      this.$refs.exhibitionFrame?.contentWindow?.postMessage(message, window.location.origin);
    },
    toggleFocus(kind) { this.focus = this.focus === kind ? '' : kind; this.$nextTick(this.measure); },
  },
};
</script>

